	GRPCStreaming     Protocol = 128 // gRPC with streaming support

	TTHeaderFramed = TTHeader | Framed
)

// String prints human readable information.
func (tp Protocol) String() string {
	switch tp {
	case PurePayload:
		return "PurePayload"
	case Framed:
		return "Framed"
	case TTHeader:
		return "TTHeader"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	}

	// Handle composite protocols not explicitly defined
	var parts []string
	if tp&TTHeader != 0 {
		parts = append(parts, "TTHeader")
	}
	if tp&Framed != 0 {
		parts = append(parts, "Framed")
	}
	if tp&HTTP != 0 {
		parts = append(parts, "HTTP")
	}
	if tp&GRPC != 0 {
		parts = append(parts, "GRPC")
	}
	if tp&HESSIAN2 != 0 {
		parts = append(parts, "HESSIAN2")
	}

	if len(parts) > 0 {
		result := parts[0]
		for i := 1; i < len(parts); i++ {
			result += "|" + parts[i]
		}
		return result
	}

	return Unknown
}

