// Dump returns the internal state of the http2Client for debugging purposes.
// The format is implementation-specific and may change between versions.
func (t *http2Client) Dump() string {
	t.mu.Lock()
	defer t.mu.Unlock()

	var buf strings.Builder
	buf.WriteString("http2Client{")
	buf.WriteString(fmt.Sprintf("remoteAddr=%s, ", t.remoteAddr))
	buf.WriteString(fmt.Sprintf("localAddr=%s, ", t.localAddr))
	buf.WriteString(fmt.Sprintf("state=%v, ", t.state))
	buf.WriteString(fmt.Sprintf("activeStreams=%d, ", len(t.activeStreams)))
	buf.WriteString(fmt.Sprintf("maxConcurrentStreams=%d, ", atomic.LoadUint32(&t.maxConcurrentStreams)))
	buf.WriteString(fmt.Sprintf("streamQuota=%d, ", atomic.LoadInt64(&t.streamQuota)))
	buf.WriteString(fmt.Sprintf("waitingStreams=%d, ", atomic.LoadUint32(&t.waitingStreams)))
	buf.WriteString(fmt.Sprintf("nextID=%d, ", t.nextID))

	goAwayStr := "none"
	select {
	case <-t.goAway:
		goAwayStr = fmt.Sprintf("received(reason=%v, prevID=%d)", t.goAwayReason, t.prevGoAwayID)
	default:
	}
	buf.WriteString(fmt.Sprintf("goAway=%s", goAwayStr))
	buf.WriteString("}")

	return buf.String()
}

